;(()=>{
  if(window.__lienCatalogRegistrationV96)return;
  window.__lienCatalogRegistrationV96=true;
  const style=document.createElement('style');
  style.textContent='#lien-catalog-toast{position:fixed;z-index:240;top:88px;right:20px;width:min(390px,calc(100vw - 32px));display:flex;align-items:flex-start;gap:12px;padding:15px 17px;border:1px solid #e5d8cf;border-radius:18px;background:#fffdfa;color:#2f2a25;box-shadow:0 20px 55px rgba(47,42,37,.18);font:600 13px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI","Yu Gothic",Meiryo,sans-serif;opacity:0;transform:translateY(-8px);pointer-events:none;transition:opacity .18s ease,transform .18s ease}#lien-catalog-toast.show{opacity:1;transform:translateY(0)}#lien-catalog-toast.success{border-color:#b9dbc5;background:#f1faf4;color:#24553b}#lien-catalog-toast.error{border-color:#efc1bb;background:#fff3f1;color:#8d332d}.lien-catalog-toast-icon{display:grid;width:28px;height:28px;flex:0 0 28px;place-items:center;border-radius:50%;background:#f2e8e1;color:#9b5647}.success .lien-catalog-toast-icon{background:#dcefe3;color:#276344}.error .lien-catalog-toast-icon{background:#f8deda;color:#9b3932}.lien-catalog-spinner{width:15px;height:15px;border:2px solid rgba(255,255,255,.45);border-top-color:#fff;border-radius:50%;animation:lienCatalogSpin .7s linear infinite}@keyframes lienCatalogSpin{to{transform:rotate(360deg)}}@media(max-width:680px){#lien-catalog-toast{top:74px;left:16px;right:16px;width:auto}}';
  document.head.appendChild(style);
  let toastTimer;
  function toast(message,state='loading',sticky=false){
    let node=document.getElementById('lien-catalog-toast');
    if(!node){node=document.createElement('div');node.id='lien-catalog-toast';node.setAttribute('role','status');node.setAttribute('aria-live','polite');document.body.appendChild(node)}
    clearTimeout(toastTimer);node.className=state;node.innerHTML='<span class="lien-catalog-toast-icon">'+(state==='loading'?'…':state==='success'?'✓':'!')+'</span><span>'+message+'</span>';requestAnimationFrame(()=>node.classList.add('show'));
    if(!sticky)toastTimer=setTimeout(()=>node.classList.remove('show'),4200)
  }
  function kindOf(form){if(form.querySelector('[name="menuName"]'))return'menu';if(form.querySelector('[name="manufacturerName"]')&&form.querySelector('[name="retailPrice"]'))return'product';return null}
  document.addEventListener('submit',async event=>{
    const form=event.target;if(!(form instanceof HTMLFormElement)||!form.closest('[role="dialog"]'))return;
    const kind=kindOf(form);if(!kind)return;
    event.preventDefault();event.stopImmediatePropagation();
    if(form.dataset.catalogSubmitting==='true')return;
    form.dataset.catalogSubmitting='true';form.setAttribute('aria-busy','true');
    const button=form.querySelector('button[type="submit"]');const original=button?button.innerHTML:'';
    if(button){button.disabled=true;button.innerHTML='<span class="lien-catalog-spinner" aria-hidden="true"></span> 登録しています…'}
    toast(kind==='menu'?'メニューを登録しています…':'商品を登録しています…','loading',true);
    const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),20000);
    try{
      const data=new FormData(form);data.set('kind',kind);
      const response=await fetch('/api/admin/catalog',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(data),credentials:'same-origin',signal:controller.signal});
      const payload=await response.json().catch(()=>({}));
      if(!response.ok||!payload.ok)throw new Error(payload.error||'登録できませんでした。');
      if(button){button.innerHTML='✓ 登録しました'}
      const reactivated=Boolean(payload.result&&payload.result.reactivated);
      toast(reactivated?'商品を販売中として再登録しました。':kind==='menu'?'メニューを登録しました。':'商品を登録しました。','success',true);
      const next=kind==='menu'?'/admin/products?section=menus&notice=menu-created':'/admin/products?notice='+(reactivated?'product-reactivated':'product-created')+'&focus='+encodeURIComponent(payload.result.id)+'#product-'+encodeURIComponent(payload.result.id);
      setTimeout(()=>location.assign(next),650);
    }catch(error){
      const message=error&&error.name==='AbortError'?'通信に時間がかかっています。接続を確認してもう一度お試しください。':error&&error.message?error.message:'登録できませんでした。';
      toast(message,'error');form.dataset.catalogSubmitting='false';form.removeAttribute('aria-busy');if(button){button.disabled=false;button.innerHTML=original}
    }finally{clearTimeout(timeout)}
  },true);
  const notice=new URLSearchParams(location.search).get('notice');
  if(notice==='menu-created'||notice==='product-created'||notice==='product-reactivated'){
    setTimeout(()=>toast(notice==='menu-created'?'メニューを登録しました。':notice==='product-reactivated'?'商品を販売中として再登録しました。':'商品を登録しました。','success'),120);
  }
})();
